import base64, json, os, urllib.parse, urllib.request
BASE='https://sanrio-fan.site/wp-json/wp/v2'
auth=base64.b64encode((os.environ['SANRIO_WP_USER']+':'+os.environ['SANRIO_WP_APP_PASSWORD']).encode()).decode()
def call(path,data=None):
 req=urllib.request.Request(BASE+path,data=json.dumps(data,ensure_ascii=False).encode() if data is not None else None,headers={'Authorization':'Basic '+auth,'Content-Type':'application/json','User-Agent':'SanrioEditorialPublisher/1.0'})
 with urllib.request.urlopen(req,timeout=45) as res: return json.load(res)
